import React, { useEffect, useRef, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { api, BACKEND_URL, fmt } from "../lib/api";
import { toast } from "sonner";

export default function Messages() {
  const { user } = useAuth();
  const [params] = useSearchParams();
  const [convs, setConvs] = useState([]);
  const [activeId, setActiveId] = useState(params.get("to") || null);
  const [other, setOther] = useState(null);
  const [thread, setThread] = useState([]);
  const [text, setText] = useState("");
  const [error, setError] = useState(null);
  const wsRef = useRef(null);
  const endRef = useRef(null);
  const activeRef = useRef(activeId);
  useEffect(() => { activeRef.current = activeId; }, [activeId]);

  const loadConvs = async () => {
    try {
      const { data } = await api.get("/messages/conversations");
      setConvs(data);
    } catch {}
  };

  useEffect(() => { loadConvs(); }, []);

  // Load thread + other user whenever activeId changes
  useEffect(() => {
    if (!activeId) return;
    setError(null);
    setThread([]);
    (async () => {
      try {
        const [{ data: t }, { data: u }] = await Promise.all([
          api.get(`/messages/thread/${activeId}`),
          api.get(`/users/${activeId}`),
        ]);
        setThread(t);
        setOther(u);
      } catch (e) {
        const msg = e.response?.data?.detail || "Could not load messages.";
        setError(msg);
        // Still load the other user's name for display
        try { const { data: u } = await api.get(`/users/${activeId}`); setOther(u); } catch {}
      }
    })();
  }, [activeId]);

  // WebSocket for real-time messages
  useEffect(() => {
    if (!user?.id) return;
    (async () => {
      try {
        const { data } = await api.post("/auth/ws-token");
        const wsUrl = BACKEND_URL.replace(/^http/, "ws") + `/api/ws/${user.id}?token=${data.token}`;
        const ws = new WebSocket(wsUrl);
        ws.onmessage = (e) => {
          try {
            const p = JSON.parse(e.data);
            if (p.type === "message") {
              const m = p.data;
              const o = activeRef.current;
              if (m.senderId === o || m.receiverId === o) {
                setThread(prev => prev.some(x => x._id === m._id) ? prev : [...prev, m]);
              }
              loadConvs();
            }
          } catch {}
        };
        wsRef.current = ws;
      } catch {}
    })();
    return () => wsRef.current?.close();
  }, [user?.id]);

  useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [thread]);

  const send = async (e) => {
    e.preventDefault();
    if (!text.trim() || !activeId) return;
    try {
      const { data } = await api.post("/messages", { receiver_id: activeId, content: text.trim() });
      setThread(prev => prev.some(x => x._id === data._id) ? prev : [...prev, data]);
      setText("");
      setError(null);
      loadConvs();
    } catch (err) {
      toast.error(fmt(err.response?.data?.detail));
    }
  };

  return (
    <div style={{ maxWidth: 1200, margin: "0 auto", padding: "2rem" }}>
      <div className="overline">Conversations</div>
      <h1 className="font-serif" style={{ fontSize: "2.5rem", color: "var(--ivy)", margin: "8px 0 1.5rem" }}>Messages</h1>

      <div className="card-editorial" style={{ display: "grid", gridTemplateColumns: "280px 1fr", height: 580 }}>

        {/* Sidebar — conversation list */}
        <div style={{ borderRight: "1px solid var(--border)", overflowY: "auto", background: "#fafaf8" }}>
          <div style={{ padding: "12px 16px", fontSize: 11, letterSpacing: "0.12em", textTransform: "uppercase", color: "var(--muted)", borderBottom: "1px solid var(--border)" }}>
            Conversations
          </div>
          {convs.length === 0 && (
            <div style={{ padding: 20, color: "var(--muted)", fontSize: 13, lineHeight: 1.5 }}>
              No conversations yet.<br />
              <span style={{ fontSize: 12 }}>Accept a mentorship request to start messaging.</span>
            </div>
          )}
          {convs.map(c => (
            <button key={c.other_id} onClick={() => setActiveId(c.other_id)} style={{
              display: "block", width: "100%", textAlign: "left",
              padding: "14px 16px", borderBottom: "1px solid var(--border)",
              background: activeId === c.other_id ? "#fff" : "transparent",
              border: "none", borderRight: activeId === c.other_id ? "3px solid var(--ivy)" : "3px solid transparent",
              cursor: "pointer",
            }}>
              <div style={{ fontWeight: 600, color: "var(--ivy)", fontSize: 14, marginBottom: 3 }}>{c.other_name}</div>
              <div style={{ fontSize: 12, color: "var(--muted)", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{c.last_message}</div>
            </button>
          ))}
        </div>

        {/* Main chat area */}
        <div style={{ display: "flex", flexDirection: "column", height: "100%" }}>
          {!activeId ? (
            <div style={{ margin: "auto", textAlign: "center", color: "var(--muted)" }}>
              <div style={{ fontSize: "2rem", marginBottom: 8 }}>💬</div>
              <p>Select a conversation or go to<br />
                <a href="/mentorship" style={{ color: "var(--accent)" }}>Mentorship</a> to start one.
              </p>
            </div>
          ) : (
            <>
              {/* Header */}
              <div style={{ padding: "14px 20px", borderBottom: "1px solid var(--border)", fontWeight: 600, color: "var(--ivy)", display: "flex", alignItems: "center", gap: 10 }}>
                <div style={{ width: 36, height: 36, borderRadius: "50%", background: "var(--ivy)", color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 700, fontSize: 14 }}>
                  {other?.name?.[0] || "?"}
                </div>
                <div>
                  <div>{other?.name || "..."}</div>
                  <div style={{ fontSize: 12, color: "var(--muted)", fontWeight: 400 }}>{other?.role} {other?.industry ? `· ${other.industry}` : ""}</div>
                </div>
              </div>

              {/* Error banner */}
              {error && (
                <div style={{ padding: "12px 20px", background: "#fef2f2", borderBottom: "1px solid #fecaca", color: "#991b1b", fontSize: 13 }}>
                  ⚠️ {error}
                </div>
              )}

              {/* Messages */}
              <div style={{ flex: 1, overflowY: "auto", padding: "16px 20px" }}>
                {thread.length === 0 && !error && (
                  <div style={{ textAlign: "center", color: "var(--muted)", marginTop: 40, fontSize: 14 }}>
                    No messages yet. Say hello! 👋
                  </div>
                )}
                {thread.map(m => {
                  const mine = m.senderId === user.id;
                  return (
                    <div key={m._id} style={{ display: "flex", justifyContent: mine ? "flex-end" : "flex-start", marginBottom: 12 }}>
                      <div>
                        <div className={mine ? "bubble-me" : "bubble-them"} style={{ padding: "10px 14px", maxWidth: 420 }}>
                          <div style={{ fontSize: 14, whiteSpace: "pre-wrap", lineHeight: 1.5 }}>{m.content}</div>
                        </div>
                        <div style={{ fontSize: 11, color: "var(--muted)", marginTop: 3, textAlign: mine ? "right" : "left" }}>
                          {new Date(m.createdAt).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}
                        </div>
                      </div>
                    </div>
                  );
                })}
                <div ref={endRef} />
              </div>

              {/* Input */}
              {!error && (
                <form onSubmit={send} style={{ padding: "12px 16px", borderTop: "1px solid var(--border)", display: "flex", gap: 8 }}>
                  <input
                    className="input"
                    placeholder="Write a message…"
                    value={text}
                    onChange={e => setText(e.target.value)}
                    style={{ flex: 1 }}
                  />
                  <button className="btn-primary" type="submit" disabled={!text.trim()}>Send</button>
                </form>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
}
